// 从指定ID删除一条笔记。
func (s *Store) Delete(ctx context.Context, id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.items, id)
	return nil
}

// 返回所有未被移除的笔记切片。
func (s *Store) List(ctx context.Context) []Note {
	out := make([]Note, 0, len(s.items))
	for _, n := range s.items {
		out = append(out, n)
	}
	return out
}
``` 风险在于.mu互斥锁可能导致并发问题，以及List方法返回所有笔记，可能存在内存消耗风险。

